// ---- GRADE DE HORARIOS (gerada dinamicamente) ----
// Slot = 20min = 1 servico. Seg-sex: 07:00-11:00 e 14:00-18:00.
// Sabado: 07:00-11:40 e 14:00-18:40. Domingo: fechado.
const DURACAO_SLOT = 20;

function paraHHMM(totalMin) {
  const h = String(Math.floor(totalMin / 60)).padStart(2, '0');
  const m = String(totalMin % 60).padStart(2, '0');
  return `${h}:${m}`;
}

function gerarBloco(inicioMin, fimMin, primeiraLinha) {
  const lista = [];
  let linha = primeiraLinha;
  for (let m = inicioMin; m < fimMin; m += DURACAO_SLOT) {
    lista.push({
      horario: `${paraHHMM(m)} à ${paraHHMM(m + DURACAO_SLOT)}`,
      inicio: paraHHMM(m),
      fim: paraHHMM(m + DURACAO_SLOT),
      linha,
    });
    linha++;
  }
  return lista;
}

function gerarGrade(ehFimDeSemana) {
  const manha = ehFimDeSemana
    ? gerarBloco(7 * 60, 11 * 60 + 40, 2)
    : gerarBloco(7 * 60, 11 * 60, 2);
  const tarde = ehFimDeSemana
    ? gerarBloco(14 * 60, 18 * 60 + 40, 2 + manha.length)
    : gerarBloco(14 * 60, 18 * 60, 2 + manha.length);
  return { manha, tarde, todos: [...manha, ...tarde] };
}

// ---- REGRA DE SERVICOS ----
// 1 servico = 20min (1 slot) | 2 servicos = 40min (2 slots seguidos) | 3 servicos = 60min (3 slots seguidos)
function categoriaServico(texto) {
  const s = texto.toString().toLowerCase();
  if (s.includes('corte')) return 'cabelo';
  if (s.includes('luz')) return 'luzes';
  if (s.includes('barba')) return 'barba';
  return null; // nao afeta a duracao (listras, sobrancelha, lavar, etc)
}

function analisarServicos(servicosRaw) {
  let lista = [];
  if (Array.isArray(servicosRaw)) {
    lista = servicosRaw;
  } else if (typeof servicosRaw === 'string' && servicosRaw.trim()) {
    lista = servicosRaw.split(',');
  }
  const todos = lista.map(s => s.toString().trim()).filter(Boolean);
  const categorias = [...new Set(todos.map(categoriaServico).filter(Boolean))];
  return { todos, categorias };
}

function formatarServicos(todos) {
  return todos.join(' + ');
}

const extrairData = $('Extrair Data Disponibilidade').first().json;

if (extrairData.aberto === false) {
  return [{
    json: {
      data: extrairData.dataCompleta,
      existeArquivo: false,
      fechado: true,
      mensagem: 'Fechado aos domingos',
      horarios: []
    }
  }];
}

const grade = gerarGrade(extrairData.ehFimDeSemana);
const { todos, categorias } = analisarServicos(extrairData.servicos);
const n = categorias.length || 1; // sem servico que afete duracao -> assume 1 slot (20min)

function janelasDoBloco(bloco) {
  const resultado = [];
  for (let i = 0; i <= bloco.length - n; i++) {
    const janela = bloco.slice(i, i + n);
    resultado.push({
      horario: `${janela[0].inicio} à ${janela[n - 1].fim}`,
      status: 'LIVRE' // arquivo do dia ainda nao existe = tudo livre
    });
  }
  return resultado;
}

const horarios = [...janelasDoBloco(grade.manha), ...janelasDoBloco(grade.tarde)];

return [{
