const inputData = $input.all();
const esperado = ($('Extrair Data').first().json.ano || '').toString().trim();

const encontrada = inputData.find(item =>
  item.json && item.json.id && item.json.name &&
  item.json.name.trim().toLowerCase() === esperado.toLowerCase()
);

if (encontrada) {
  return [{
    json: {
      length: 1,
      existe: true,
      id: encontrada.json.id,
      name: encontrada.json.name,
      mensagem: "Pasta encontrada"
    }
  }];
}

return [{
  json: {
    length: 0,
    existe: false,
    mensagem: "Pasta não encontrada"
  }
}];

const primeiroItem = $input.first();

if (!primeiroItem) {
  return [{ json: { erro: "Nenhum dado recebido" } }];
}

const jsonData = primeiroItem.json || {};

const fonte = {
  ...(jsonData.query || {}),
  ...(jsonData.params?.query || {}),
  ...(jsonData.body || {}),
  ...jsonData
};

let data = fonte.data;
if (!data && typeof jsonData === 'object') {
  for (const key of Object.keys(jsonData)) {
    if (jsonData[key] && typeof jsonData[key] === 'object' && jsonData[key].data) {
      data = jsonData[key].data;
      break;
    }
  }
}

if (!data) {
  return [{
    json: {
      erro: "Data nao fornecida. Use ?data=07-07-2026 ou envie no body",
      debug: jsonData
    }
  }];
}

const partes = data.split('-');
const dia = partes[0];
const mes = partes[1];
const ano = partes[2];

const nomesMeses = {
  '01': 'Janeiro', '02': 'Fevereiro', '03': 'Marco',
  '04': 'Abril', '05': 'Maio', '06': 'Junho',
  '07': 'Julho', '08': 'Agosto', '09': 'Setembro',
  '10': 'Outubro', '11': 'Novembro', '12': 'Dezembro'
};

const nomeMes = nomesMeses[mes] || mes;

// 0=domingo, 1=segunda ... 6=sabado
const diaSemana = new Date(Number(ano), Number(mes) - 1, Number(dia)).getDay();
const ehFimDeSemana = diaSemana === 6; // so sabado usa a grade de fim de semana
const aberto = diaSemana !== 0; // fechado aos domingos

return [{
  json: {
    dia: dia,
    mes: mes,
    ano: ano,
    nomeMes: nomeMes,
    nomeMesUpper: nomeMes.toUpperCase(),
    dataCompleta: data,
    caminhoAno: ano,
    caminhoMes: `${ano}/${nomeMes.toUpperCase()}`,
    nomeArquivo: `${data}.xlsx`,
    diaSemana,
    ehFimDeSemana,
    aberto,
    // dados do cliente, preservados ate o fim do fluxo
    horario: fonte.horario || '',
    cliente: fonte.cliente || '',
    telefone: fonte.telefone || '',
    servicos: fonte.servicos || ''
  }
}];
